const R = $json.valueRanges || [];
const pick = (n) => (R.find(x => String(x.range||'').indexOf(n) === 0) || {}).values || [];
const crit = pick('INVESTOR_CRITERIA');
const inv  = pick('INVESTORS!');
const g = (row,i) => (row && row[i] != null) ? String(row[i]).trim() : '';

const TARGET = 287;

// Guard 1: the INVESTORS row must exist and be Dexter
const ivRow = inv[TARGET-1];
if (!ivRow || g(ivRow,0).toLowerCase().indexOf('dexter') < 0) throw new Error('INVESTORS row ' + TARGET + ' is not Dexter: ' + g(ivRow,0));

// Guard 2: no criteria row may already point at 287
for (let i = 1; i < crit.length; i++) { if (g(crit[i],0) === String(TARGET)) throw new Error('criteria row already exists for ' + TARGET + ' at sheet row ' + (i+1)); }

// Guard 3: append strictly AFTER the last row that has any data
let lastData = 0;
for (let i = 1; i < crit.length; i++) { const r = crit[i]; if (r && r.some(c => String(c||'').trim() !== '')) lastData = i; }
const newRow = lastData + 2;
const chk = crit[newRow-1];
if (chk && chk.some(c => String(c||'').trim() !== '')) throw new Error('target row ' + newRow + ' is not empty');

const THESIS = 'Thesis as stated by Dexter in writing (email to investors@, Sep 2026): "Cheque Size: $100k-$500k / INR 1-4 Cr. Stage: Pre-Seed and Seed with select Pre-Series A - in Pre-Series A, not much into bridge rounds, but love maiden rounds. Sector: Sector Agnostic. Preferred / Focused Sectors: B2B SaaS, AI, FinTech, Consumer (Tech and Brand) and HealthTech. Negative Sectors: EV, Loyalty Tech, Renewables, Crypto / Web 3, Farm Mechanization. For Negative sectors in-case the team is exceptional (2x founder, CXO experience, top domain knowledge) we are open to evaluating. Any deal not in negative sectors, we are happy to look at on a case by case basis." India micro-VC, began 2020 as Dexter Angels; 43 companies. Screens founding team first, then large growing markets, then execution and customer evidence; avoids small hyper-competitive markets.';

const NOTES = '2026-09-23: row created from Dexter’s own written thesis. sector_mode AGNOSTIC because they say "Sector Agnostic"; their negative list is encoded in sectors_excluded. Two caveats: they exclude FARM MECHANISATION specifically, not all of AGRITECH, and their Crypto/Web3 exclusion has no matching sector code - both are judgement calls to revisit. They will still look at a negative-sector deal if the team is exceptional (2x founder / CXO / top domain knowledge).';

const cells = {
  A: String(TARGET),
  B: g(ivRow,0),
  D: 'ACTIVE',
  E: 'USER',
  G: 'AGNOSTIC',
  I: 'EV_CLEAN_MOBILITY, CLIMATE_ENERGY, MARTECH_ADTECH, AGRITECH',
  L: 'PRE_SEED',
  M: 'PRE_SERIES_A',
  N: '1',
  T: 'India',
  V: THESIS,
  W: 'Email from deals@dexter.ventures to investors@sidanaventures.com, Sep 2026 (Body & Beyond and Glazia Windoors threads); dexter.ventures; tracxn.com Dexter Ventures',
  Y: 'HIGH'
};

const data = Object.entries(cells).map(([col,val]) => ({ range: 'INVESTOR_CRITERIA!' + col + newRow, values: [[val]] }));
data.push({ range: 'INVESTOR_CRITERIA!Z' + newRow, values: [[NOTES]] });

// also fill the INVESTORS cheque cell if still blank
const extra = [];
if (!g(ivRow,6)) { data.push({ range: 'INVESTORS!G' + TARGET, values: [['US$100-500K (INR 1-4 Cr)']] }); extra.push('INVESTORS G' + TARGET + ' cheque'); }

return [{ json: { body: { valueInputOption: 'RAW', data: data }, new_criteria_row: newRow, cells: data.length, also: extra, investor: g(ivRow,0) } }];
